<script setup>
import { computed, onBeforeUnmount, onMounted, ref } from 'vue'
import { useRoute, useRouter } from 'vue-router'
import http from '../../api/http'
import { getAccessToken } from '../../api/auth'
const route=useRoute();const router=useRouter();const token=ref('');const questions=ref([]);const answers=ref({});const config=ref({});const result=ref(null);const expiry=ref(0);const now=ref(Date.now());const loading=ref(true);const error=ref('');const saving=ref(false);const saved=ref(false);let interval
async function choose(questionId,key){if(answers.value[questionId]||seconds.value===0)return;answers.value={...answers.value,[questionId]:key};try{await http.put(`/gk/exams/${encodeURIComponent(token.value)}/answers`,{answers:answers.value})}catch(e){error.value=e.response?.data?.message||'উত্তর সংরক্ষণ হয়নি।'}}const seconds=computed(()=>Math.max(0,Math.ceil((expiry.value-now.value)/1000)));const clock=computed(()=>`${String(Math.floor(seconds.value/60)).padStart(2,'0')}:${String(seconds.value%60).padStart(2,'0')}`)
function number(i){return config.value.numbering_style==='bangla'?String(i+1).replace(/[0-9]/g,n=>'০১২৩৪৫৬৭৮৯'[n]):i+1}
async function submit(auto=false){if(result.value||!token.value)return;try{const {data}=await http.post(`/gk/exams/${encodeURIComponent(token.value)}/submit`,auto?{answers:{}}:{answers:answers.value});result.value=data.result;saved.value=data.saved}catch(e){error.value=e.response?.data?.message||'ফলাফল জমা হয়নি।'}}
async function save(){if(!getAccessToken()){await router.push({name:'account',query:{redirect:route.fullPath+'?save=1'}});return}saving.value=true;try{await http.post(`/gk/exams/${encodeURIComponent(token.value)}/save`);saved.value=true}catch(e){error.value=e.response?.data?.message||'ফলাফল সংরক্ষণ হয়নি।'}finally{saving.value=false}}
onMounted(async()=>{try{const {data}=await http.post(`/gk/exam-papers/${route.params.paperId}/start`);token.value=data.exam_token;questions.value=data.questions;config.value=data.exam_config;expiry.value=new Date(data.expires_at).getTime()}catch(e){error.value=e.response?.data?.message||'পরীক্ষা শুরু করা যায়নি।'}finally{loading.value=false}interval=setInterval(()=>{now.value=Date.now();if(!loading.value&&!result.value&&seconds.value===0)submit(true)},500)})
onBeforeUnmount(()=>clearInterval(interval))
</script>
<template><main class="container-page py-8"><div class="mx-auto max-w-5xl"><header class="mb-5 grid grid-cols-3 items-center rounded-2xl border bg-white p-4"><RouterLink to="/" class="font-extrabold text-emerald-800">সহজপাঠ</RouterLink><h1 class="text-center font-black md:text-xl">{{ config.title||'MCQ পরীক্ষা' }}</h1><b class="text-right font-mono text-rose-700">{{ clock }}</b></header><p v-if="loading" class="surface p-10 text-center">পরীক্ষা প্রস্তুত হচ্ছে…</p><p v-else-if="error&&!questions.length" class="surface p-8 text-center text-rose-700">{{ error }} <RouterLink to="/gk/exam-categories" class="font-bold">বিভাগে ফিরুন</RouterLink></p><template v-else-if="result"><section class="surface mb-5 p-7 text-center"><p class="text-sm font-bold text-emerald-700">পরীক্ষার ফলাফল</p><p class="my-2 text-5xl font-black">{{ result.score }}</p><p>মোট {{ result.total_marks }} নম্বর · সঠিক {{ result.correct_count }} · ভুল {{ result.wrong_count }} · কাটা {{ result.wrong_cut_marks }}</p></section><section class="grid gap-3"><article v-for="item in result.wrong_answers" :key="item.number" class="surface p-5"><b>{{ item.number }}. {{ item.question }}</b><p class="mt-2 text-rose-700">আপনার উত্তর: {{ item.selected_answer }}</p><p class="font-bold text-emerald-700">সঠিক উত্তর: {{ item.correct_answer }}</p></article></section><div class="mt-5 flex justify-center gap-3"><button v-if="!saved" class="btn-primary" :disabled="saving" @click="save">{{ saving?'সংরক্ষণ হচ্ছে…':'Save this record' }}</button><RouterLink v-else to="/profile" class="btn-primary">Profile দেখুন</RouterLink><RouterLink to="/gk/exam-categories" class="rounded-xl border px-4 py-3">বিভাগে ফিরুন</RouterLink></div><p v-if="error" class="mt-4 text-center text-rose-700">{{ error }}</p></template><template v-else><div class="mb-4 flex justify-between rounded-2xl bg-emerald-950 p-4 text-white"><b>{{ questions.length }} প্রশ্ন · প্রতি প্রশ্ন ১ নম্বর · ভুলে ১ নম্বর কাটা</b><span class="font-mono text-xl">{{ clock }}</span></div><div class="grid gap-4" :class="[2,5].includes(config.layout_template)?'md:grid-cols-2':''"><article v-for="(q,i) in questions" :key="q.id" class="surface p-5"><p class="font-extrabold leading-7">{{ number(i) }}. {{ q.question }}</p><div class="mt-3 grid gap-2"><label v-for="key in ['a','b','c','d']" :key="key" class="flex gap-2 rounded-lg border p-3 text-sm" :class="answers[q.id]===key?'border-emerald-600 bg-emerald-50':'border-slate-200'"><input type="radio" :name="'q'+q.id" :value="key" :disabled="!!answers[q.id]||seconds===0" @change="choose(q.id,key)"><span>{{ config.option_style==='alphabet'?key.toUpperCase()+')':'◯' }} {{ q['option_'+key] }}</span></label></div></article></div><div class="mt-5 text-center"><button class="btn-primary" @click="submit()">পরীক্ষা জমা দিন</button><p class="mt-2 text-xs text-slate-500">উত্তর বেছে নিলে সেটি আর পরিবর্তন করা যাবে না।</p></div></template></div></main></template>